import{_ as e,a as s,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"MySQL 连接与认证插件排障","description":"先给出现行连接分层，再以明确版本边界收录旧 2059 记录。","frontmatter":{"title":"MySQL 连接与认证插件排障","description":"先给出现行连接分层，再以明确版本边界收录旧 2059 记录。","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"排错","scope":"general","audience":"general","group":"数据库与存储","summary":"先给出现行连接分层，再以明确版本边界收录旧 2059 记录。","status":"active","related":[{"title":"01 · 连接数据库与准备练习数据","link":"/middleware/mysql/base/mysql-crash-course-2/01-start","kind":"知识专题","scope":"general","audience":"general"},{"title":"02 · 检索、排序与条件过滤","link":"/middleware/mysql/base/mysql-crash-course-2/02-filtering","kind":"知识专题","scope":"general","audience":"general"},{"title":"03 · 计算、汇总与多表查询","link":"/middleware/mysql/base/mysql-crash-course-2/03-querying","kind":"知识专题","scope":"general","audience":"general"},{"title":"04 · 数据写入、表结构与视图","link":"/middleware/mysql/base/mysql-crash-course-2/04-tables","kind":"知识专题","scope":"general","audience":"general"},{"title":"05 · 存储程序与事务边界","link":"/middleware/mysql/base/mysql-crash-course-2/05-programming","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MySQL 监控部署","link":"/middleware/mysql/plus/practice/mysql-monitor"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MySQL 监控部署","link":"/middleware/mysql/plus/practice/mysql-monitor"},"next":false},"headers":[],"relativePath":"middleware/mysql/connection-diagnosis.md","filePath":"middleware/mysql/connection-diagnosis.md"}'),l={name:"middleware/mysql/connection-diagnosis.md"};function r(n,a,o,p,d,h){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="mysql-连接与认证插件排障" tabindex="-1">MySQL 连接与认证插件排障 <a class="header-anchor" href="#mysql-连接与认证插件排障" aria-label="Permalink to &quot;MySQL 连接与认证插件排障&quot;">​</a></h1><h2 id="part-1" tabindex="-1">MySQL 连接失败 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;MySQL 连接失败 {#part-1}&quot;">​</a></h2><p>按网络、监听端口、账号认证的顺序定位错误。下列命令显式指定 TCP；Unix 上 localhost 默认可能走 socket，单写 -P 不能保证测试该端口。<code>&lt;host&gt;</code>、<code>&lt;user&gt;</code> 是需要替换的占位符。</p><p>先确认客户端所在主机、目标地址和端口。使用 -p 让客户端交互式询问密码，不要把密码放在命令行参数里。</p><h3 id="part-1-排查步骤" tabindex="-1">排查步骤 <a class="header-anchor" href="#part-1-排查步骤" aria-label="Permalink to &quot;排查步骤 {#part-1-排查步骤}&quot;">​</a></h3><h4 id="part-1-_1-测试服务器是否响应" tabindex="-1">1. 测试服务器是否响应 <a class="header-anchor" href="#part-1-_1-测试服务器是否响应" aria-label="Permalink to &quot;1. 测试服务器是否响应 {#part-1-_1-测试服务器是否响应}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysqladmin --protocol=TCP -h &lt;host&gt; -P 3306 -u &lt;user&gt; -p ping</span></span></code></pre></div><p><strong>预期结果:</strong> 收到服务器响应；即使认证失败，也可区分网络与认证路径。</p><h4 id="part-1-_2-获取准确的连接错误" tabindex="-1">2. 获取准确的连接错误 <a class="header-anchor" href="#part-1-_2-获取准确的连接错误" aria-label="Permalink to &quot;2. 获取准确的连接错误 {#part-1-_2-获取准确的连接错误}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql --protocol=TCP -h &lt;host&gt; -P 3306 -u &lt;user&gt; -p</span></span></code></pre></div><p><strong>预期结果:</strong> 记录错误代码和目标地址，确认连接走 TCP 而非意外的本地 socket。</p><h4 id="part-1-_3-连接成功后确认身份和服务器" tabindex="-1">3. 连接成功后确认身份和服务器 <a class="header-anchor" href="#part-1-_3-连接成功后确认身份和服务器" aria-label="Permalink to &quot;3. 连接成功后确认身份和服务器 {#part-1-_3-连接成功后确认身份和服务器}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql --protocol=TCP -h &lt;host&gt; -P 3306 -u &lt;user&gt; -p -e &quot;SELECT CURRENT_USER(), @@hostname;&quot;</span></span></code></pre></div><p><strong>预期结果:</strong> 输出账号和服务器名与预期一致，避免连到错误实例。</p><h3 id="part-1-常见报错" tabindex="-1">常见报错 <a class="header-anchor" href="#part-1-常见报错" aria-label="Permalink to &quot;常见报错 {#part-1-常见报错}&quot;">​</a></h3><h4 id="part-1-error-2003-connection-refused" tabindex="-1">ERROR 2003 / connection refused <a class="header-anchor" href="#part-1-error-2003-connection-refused" aria-label="Permalink to &quot;ERROR 2003 / connection refused {#part-1-error-2003-connection-refused}&quot;">​</a></h4><p><strong>原因:</strong> 目标端口没有可达监听服务，或网络策略阻断。</p><p><strong>处理方式:</strong> 检查主机名、端口、服务监听地址与防火墙；不要先修改账号。</p><h4 id="part-1-error-1045-access-denied" tabindex="-1">ERROR 1045 access denied <a class="header-anchor" href="#part-1-error-1045-access-denied" aria-label="Permalink to &quot;ERROR 1045 access denied {#part-1-error-1045-access-denied}&quot;">​</a></h4><p><strong>原因:</strong> 用户名、密码或来源主机授权不匹配。</p><p><strong>处理方式:</strong> 核对账号及其允许的来源主机，按最小权限修正凭据或授权。</p><h3 id="part-1-相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#part-1-相关文档" aria-label="Permalink to &quot;相关文档 {#part-1-相关文档}&quot;">​</a></h3><ul><li><a href="/middleware/mysql/plus/ecosystem/mysql-general-general#entry-mysql-0fd5df800c">mysql</a></li><li><a href="https://dev.mysql.com/doc/refman/8.4/en/mysqladmin.html" target="_blank" rel="noopener noreferrer">mysqladmin</a></li></ul><h3 id="part-1-官方资料" tabindex="-1">官方资料 <a class="header-anchor" href="#part-1-官方资料" aria-label="Permalink to &quot;官方资料 {#part-1-官方资料}&quot;">​</a></h3><ul><li><a href="https://dev.mysql.com/doc/refman/8.4/en/can-not-connect-to-server.html" target="_blank" rel="noopener noreferrer">https://dev.mysql.com/doc/refman/8.4/en/can-not-connect-to-server.html</a></li></ul><h2 id="part-2" tabindex="-1">MySQL 认证插件连接故障 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;MySQL 认证插件连接故障 {#part-2}&quot;">​</a></h2><blockquote><p><strong>M4版本边界（2026-10-17）：</strong> 下方是旧客户端2059错误的原始处理记录，包含旧认证插件命令及sqlALTER拼写问题，不是8.4可直接执行的解法。MySQL8.4默认禁用mysql_native_password；应先升级兼容caching_sha2_password的客户端/驱动。现行<a href="/middleware/mysql/plus/practice/operations#errors">连接认证排查</a>提供分层步骤，保留原记录仅供追溯。</p></blockquote><blockquote><p>此记录针对旧客户端不支持 caching_sha2_password 的情形。下方改认证插件是当时的处理记录；应先核对客户端与服务端版本，避免直接套用到当前环境。</p></blockquote><p><span id="part-2-mysqlerrorall"></span></p><h3 id="part-2-连接失败" tabindex="-1">连接失败 <a class="header-anchor" href="#part-2-连接失败" aria-label="Permalink to &quot;连接失败 {#part-2-连接失败}&quot;">​</a></h3><blockquote><p><code>2059 - Authentication plugin &#39;caching_sha2_password&#39; cannot be loaded: dlopen(../Frameworks/caching_sha2_password.so, 2): image not found</code></p></blockquote><ul><li><p><code>mysql -uroot -ppassword</code> #登录</p></li><li><p><code>use mysql;</code> #选择数据库</p></li><li><p>远程连接请将<code>&#39;localhost&#39;换成&#39;%&#39;</code></p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  sqlALTER USER </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;root&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IDENTIFIED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;example-user&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EXPIRE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NEVER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; #更改加密方式</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> USER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;root&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IDENTIFIED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WITH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mysql_native_password </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;example-user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; #更新用户密码</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  FLUSH PRIVILEGES; #刷新权限</span></span></code></pre></div></li><li><p><code>ALTER USER &#39;root&#39;@&#39;%&#39; IDENTIFIED WITH mysql_native_password BY &#39;123456&#39;;</code></p></li></ul>`,32)])])}const g=e(l,[["render",r]]);export{k as __pageData,g as default};
